{
  "steps": [
    {
      "id": "s1",
      "description": "Use list_documents to identify all available project documents, then use read_document to read candidate_specs.md to understand the three candidate absorber materials and their properties, and read any other relevant documents about design requirements and constraints (particularly regarding hands-on maintenance and radiation safety)."
    },
    {
      "id": "s2",
      "description": "Based on the candidate materials identified in s1, run simulate_resolution for each of the three materials at a middle-range thickness (e.g., 5mm) to establish baseline energy resolution performance and identify which material(s) show the most promise."
    },
    {
      "id": "s3",
      "description": "For the most promising material(s) from s2, run simulate_resolution at multiple plate thicknesses across the allowed range (2mm, 4mm, 6mm, 8mm, 10mm) to map out the energy resolution versus thickness relationship and identify the optimal thickness."
    },
    {
      "id": "s4",
      "description": "If multiple materials show similar performance, verify hands-on maintenance compatibility by checking activation/radiation safety constraints from the project documents, then run additional simulations if needed to distinguish between close candidates."
    },
    {
      "id": "s5",
      "description": "Use record_results to document all simulation results (material, thickness, and resolution values), identify the configuration with the best energy resolution at 100 GeV that meets all constraints, and record the final recommended absorber material and plate thickness with supporting rationale."
    }
  ]
}
```
